import{_ as t,a0 as l,w as c,s as d,I as o,x as s,a1 as a,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux DNS 查询剖析（第二部分） | LCTT x X-CMD","titleTemplate":false,"description":"Linux DNS 查询剖析（第二部分） | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux DNS 查询剖析（第二部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux DNS 查询剖析（第二部分） | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180618 Anatomy of a Linux DNS Lookup - Part II","title":"Linux DNS 查询剖析（第二部分）","tag":"201808","desc":""},"relativePath":"201808/20180618 Anatomy of a Linux DNS Lookup - Part II.md","filePath":"[post].md"}'),r={name:"201808/20180618 Anatomy of a Linux DNS Lookup - Part II.md"};function h(u,e,f,g,k,m){const n=l("Link");return c(),d("div",null,[e[19]||(e[19]=o("h1",{id:"linux-dns-查询剖析-第二部分",tabindex:"-1"},[s("Linux DNS 查询剖析（第二部分） "),o("a",{class:"header-anchor",href:"#linux-dns-查询剖析-第二部分","aria-label":"Permalink to “Linux DNS 查询剖析（第二部分）”"},"​")],-1)),o("p",null,[e[1]||(e[1]=s("在 ",-1)),a(n,{href:"https://linux.cn/article-9943-1.html"},{default:i(()=>[...e[0]||(e[0]=[s("Linux DNS 查询剖析 - 第一部分",-1)])]),_:1}),e[2]||(e[2]=s(" 中，我介绍了：",-1))]),e[20]||(e[20]=p("<ul><li><code>nsswitch</code></li><li><code>/etc/hosts</code></li><li><code>/etc/resolv.conf</code></li><li><code>ping</code> 与 <code>host</code> 查询方式对比</li></ul><p>并且发现大多数程序选择要查询的 DNS 服务器时会参考 <code>/etc/resolv.conf</code> 配置文件。</p><p>这种方式在 Linux 上比较普遍[^1]。虽然我使用了特定的发行版 Ubuntu，但背后的原理与 Debian 甚至是那些基于 CentOS 的发行版有相通的地方；当然，与更低或更高的 Ubuntu 版本相比，差异还是存在的。</p>",3)),o("p",null,[e[4]||(e[4]=s("[^1]: 事实上，这是相对于 POSIX 标准的，故不限于 Linux （我从上一篇文章的一条极好的",-1)),a(n,{href:"https://zwischenzugs.com/2018/06/08/anatomy-of-a-linux-dns-lookup-part-i/#comment-2312"},{default:i(()=>[...e[3]||(e[3]=[s("回复",-1)])]),_:1}),e[5]||(e[5]=s("中了解到这一点）",-1))]),e[21]||(e[21]=p(`<p>也就是说，接下来，你主机上的行为很可能与我描述的不一致。</p><p>在第二部分中，我将介绍 <code>resolv.conf</code> 的更新机制、<code>systemctl restart networking</code> 命令的运行机制 ，以及 <code>dhclient</code> 是如何参与其中。</p><h3 id="_1-手动更新-etc-resolv-conf" tabindex="-1">1) 手动更新 /etc/resolv.conf <a class="header-anchor" href="#_1-手动更新-etc-resolv-conf" aria-label="Permalink to “1) 手动更新 /etc/resolv.conf”">​</a></h3><p>我们知道 <code>/etc/resolv.conf</code> （有极大的可能性）被用到，故你自然可以通过该文件增加一个 <code>nameserver</code>，那么主机也将会（与已有的 <code>nameserver</code> 一起）使用新加入的 <code>nameserver</code> 吧？</p><p>你可以尝试如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo nameserver 10.10.10.10 &gt;&gt; /etc/resolv.conf</span></span></code></pre></div><p>看上去新的 <code>nameserver</code> 已经加入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span>
<span class="line"><span>nameserver 10.10.10.10</span></span></code></pre></div><p>但主机网络服务重启后问题出现了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart networking</span></span>
<span class="line"><span>$ cat /etc/resolv.conf</span></span>
<span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span></code></pre></div><p>我们的 <code>10.10.10.10</code> 的 <code>nameserver</code> 不见了！</p><p>在上一篇文章中我们忽略了这一点，本文进行补充说明。</p><h3 id="_2-resolvconf" tabindex="-1">2) resolvconf <a class="header-anchor" href="#_2-resolvconf" aria-label="Permalink to “2) resolvconf”">​</a></h3><p>你在 <code>/etc/resolv.conf</code> 文件中看到 <code>generated by resolvconf</code> 词组了吧？这就是我们的线索。</p><p>如果深入研究 <code>systemctl restart networking</code> 命令，你会发现它做了很多事情，结束时调用了 <code>/etc/network/if-up.d/000resolvconf</code> 脚本。在该脚本中，可以发现一次对 <code>resolvconf</code> 命令的调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/resolvconf -a &quot;\${IFACE}.\${ADDRFAM}&quot;</span></span></code></pre></div><p>稍微研究一下 man 手册，发现<code>-a</code> 参数允许我们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Add or overwrite the record IFACE.PROG then run the update scripts</span></span>
<span class="line"><span>if updating is enabled.</span></span></code></pre></div><p>（增加或覆盖 IFACE.PROG 记录，如果开启更新选项，则运行更新脚本）</p><p>故而也许我们可以直接调用该命令增加 <code>namserver</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;nameserver 10.10.10.10&#39; | /sbin/resolvconf -a enp0s8.inet</span></span></code></pre></div><p>测试表明确实可以！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/resolv.conf  | grep nameserver</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>nameserver 10.10.10.10</span></span></code></pre></div><p>是否已经找到答案，这就是 <code>/etc/resolv.conf</code> 更新的逻辑？调用 <code>resolvconf</code> 将 <code>nameserver</code> 添加到某个地方的数据库，然后（“如果配置了更新”，先不管具体什么含义）更新 <code>resolv.conf</code> 文件。</p><p>并非如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart networking</span></span>
<span class="line"><span>root@linuxdns1:/etc# cat /etc/resolv.conf </span></span>
<span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span></code></pre></div><p>呃！（网络服务重启后）新增的 <code>nameserver</code> 再次消失了。</p><p>可见，<code>systemctl restart networking</code> 不仅仅运行了 <code>resolvconf</code>，还在其它地方获取 <code>nameserver</code> 信息。具体是哪里呢？</p><h3 id="_3-ifup-ifdown" tabindex="-1">3) ifup/ifdown <a class="header-anchor" href="#_3-ifup-ifdown" aria-label="Permalink to “3) ifup/ifdown”">​</a></h3><p>继续深入研究 <code>systemctl restart networking</code>，发现它完成了一系列工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /lib/systemd/system/networking.service</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=oneshot</span></span>
<span class="line"><span>EnvironmentFile=-/etc/default/networking</span></span>
<span class="line"><span>ExecStartPre=-/bin/sh -c &#39;[ &quot;$CONFIGURE_INTERFACES&quot; != &quot;no&quot; ] &amp;&amp; [ -n &quot;$(ifquery --read-environment --list --exclude=lo)&quot; ] &amp;&amp; udevadm settle&#39;</span></span>
<span class="line"><span>ExecStart=/sbin/ifup -a --read-environment</span></span>
<span class="line"><span>ExecStop=/sbin/ifdown -a --read-environment --exclude=lo</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>首先，网络服务的重启实质是运行一个<ruby>单触发<rt>oneshot</rt></ruby>的脚本，脚本包含如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/ifdown -a --read-environment --exclude=lo</span></span>
<span class="line"><span>/bin/sh -c &#39;[ &quot;$CONFIGURE_INTERFACES&quot; != &quot;no&quot; ] &amp;&amp; [ -n &quot;$(ifquery --read-environment --list --exclude=lo)&quot; ] &amp;&amp; udevadm settle&#39;</span></span>
<span class="line"><span>/sbin/ifup -a --read-environment</span></span></code></pre></div><p>第一行使用 <code>ifdown</code> 关闭全部的网络接口，但<ruby>本地回环<rt>local, lo</rt></ruby>接口除外。[^2]</p><p>[^2]: 我不明白为何这没有导致我例子中的 vagrant 会话中断 （有谁明白吗？）。</p><p>（LCTT 译注：其实这是因为很快就又启动了接口，间隔的时间没有超过 TCP 连接的超时时间，有人在评论中也做了类似回复）</p><p>第二行用于确认系统已经完成关闭网络接口相关的全部工作，以便下一步使用 <code>ifup</code> 启动接口。这也让我们了解到，网络服务实质运行的就是 <code>ifdown</code> 和 <code>ifup</code>。</p><p>文档中没有找到 <code>--read-environment</code> 参数的说明，该参数为 <code>systemctl</code> 正常工作所需。很多人以文档不完善为由不喜欢 <code>systemctl</code>。</p><p>很好。那么 <code>ifup</code> （和其成对出现的 <code>ifdown</code>） 到底做了哪些工作呢？长话短说，它运行了 <code>/etc/network/if-pre-up.d/</code> 和 <code>/etc/network/if-up.d/</code> 目录下的全部脚本；期间，这些脚本也可能会调用另外的脚本，依此类推。</p><p>其中一件工作就是运行了 <code>dhclient</code>，但我还不完全确定具体的机理，也许 <code>udev</code> 参与其中。</p><h3 id="_4-dhclient" tabindex="-1">4) dhclient <a class="header-anchor" href="#_4-dhclient" aria-label="Permalink to “4) dhclient”">​</a></h3><p><code>dhclient</code> 是一个程序，用于与 DHCP 服务器协商对应网络接口应该使用的 IP 地址的详细信息。同时，它也可以获取可用的 DNS 服务器并将其替换到 <code>/etc/resolv.conf</code> 中。</p><p>让我们开始跟踪并模拟它的行为，但仅在我实验虚拟机的 <code>enp0s3</code> 接口上。事先已经删除 <code>/etc/resolv.conf</code> 文件中的 nameserver 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/nameserver.*/d&#39; /run/resolvconf/resolv.conf</span></span>
<span class="line"><span>$ cat /etc/resolv.conf | grep nameserver</span></span>
<span class="line"><span>$ dhclient -r enp0s3 &amp;&amp; dhclient -v enp0s3</span></span>
<span class="line"><span>Killed old client process</span></span>
<span class="line"><span>Internet Systems Consortium DHCP Client 4.3.3</span></span>
<span class="line"><span>Copyright 2004-2015 Internet Systems Consortium.</span></span>
<span class="line"><span>All rights reserved.</span></span>
<span class="line"><span>For info, please visit https://www.isc.org/software/dhcp/</span></span>
<span class="line"><span>Listening on LPF/enp0s8/08:00:27:1c:85:19</span></span>
<span class="line"><span>Sending on   LPF/enp0s8/08:00:27:1c:85:19</span></span>
<span class="line"><span>Sending on   Socket/fallback</span></span>
<span class="line"><span>DHCPDISCOVER on enp0s8 to 255.255.255.255 port 67 interval 3 (xid=0xf2f2513e)</span></span>
<span class="line"><span>DHCPREQUEST of 172.28.128.3 on enp0s8 to 255.255.255.255 port 67 (xid=0x3e51f2f2)</span></span>
<span class="line"><span>DHCPOFFER of 172.28.128.3 from 172.28.128.2</span></span>
<span class="line"><span>DHCPACK of 172.28.128.3 from 172.28.128.2</span></span>
<span class="line"><span>bound to 172.28.128.3 -- renewal in 519 seconds.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /etc/resolv.conf | grep nameserver</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span></code></pre></div><p>可见这就是 <code>nameserver</code> 的来源。</p><p>但稍等一下，命令中的 <code>/run/resolvconf/resolv.conf</code> 是哪个文件，不应该是 <code>/etc/resolv.conf</code> 吗？</p><p>事实上，<code>/etc/resolv.conf</code> 并不一定只是一个普通文本文件。</p><p>在我的虚拟机上，它是一个软链接，指向位于 <code>/run/resolvconf</code> 目录下的“真实文件”。这也暗示了我们，该文件是在系统启动时生成的；同时，这也是该文件注释告诉我们不要直接修改该文件的原因。</p><p>（LCTT 译注：在 CentOS 7 中，没有 <code>resolvconf</code> 命令，<code>/etc/resolv.conf</code> 也不是软链接）</p><p>假如上面命令中 <code>sed</code> 命令直接处理 <code>/etc/resolv.conf</code> 文件，效果是不同的，会有警告消息告知待操作的文件不能是软链接（<code>sed -i</code> 无法很好的处理软链接，它只会创建一个新文件）。</p><p>（LCTT 译注：CentOS 7 测试时，<code>sed -i</code> 命令操作软链接并没有警告，但确实创建了新文件取代软链接）</p><p>如果你继续深入查看配置文件 <code>/etc/dhcp/dhclient.conf</code> 的 <code>supersede</code> 部分，你会发现 <code>dhclient</code> 可以覆盖 DHCP 提供的 DNS 服务器。</p><p><img src="https://zwischenzugs.files.wordpress.com/2018/06/linux-dns-2-2.png?w=525" alt="linux-dns-2 (2)"></p><p><em>（大致）准确的关系图</em></p><hr><h3 id="第二部分的结束语" tabindex="-1">第二部分的结束语 <a class="header-anchor" href="#第二部分的结束语" aria-label="Permalink to “第二部分的结束语”">​</a></h3><p>第二部分到此结束。信不信由你，这是一个某种程度上简化的流程版本，但我尽量保留重要和值得了解的部分，让你不会感到无趣。大部分内容都是围绕实际脚本的运行展开的。</p><p>但我们的工作还没有结束，在第三部分，我们会介绍这些之上的更多层次。</p><p>让我们简要列出我们已经介绍过的内容：</p><ul><li><code>nsswitch</code></li><li><code>/etc/hosts</code></li><li><code>/etc/resolv.conf</code></li><li><code>/run/resolvconf/resolv.conf</code></li><li><code>systemd</code> 和网络服务</li><li><code>ifup</code> 和 <code>ifdown</code></li><li><code>dhclient</code></li><li><code>resolvconf</code></li></ul><hr>`,61)),o("p",null,[e[7]||(e[7]=s("via: ",-1)),a(n,{href:"https://zwischenzugs.com/2018/06/18/anatomy-of-a-linux-dns-lookup-part-ii/"},{default:i(()=>[...e[6]||(e[6]=[s("https://zwischenzugs.com/2018/06/18/anatomy-of-a-linux-dns-lookup-part-ii/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=s("作者：",-1)),a(n,{href:"https://zwischenzugs.com/"},{default:i(()=>[...e[8]||(e[8]=[s("ZWISCHENZUGS",-1)])]),_:1}),e[12]||(e[12]=s(" 译者：",-1)),a(n,{href:"https://github.com/pinewall"},{default:i(()=>[...e[9]||(e[9]=[s("pinewall",-1)])]),_:1}),e[13]||(e[13]=s(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=s("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[s("Linux中国",-1)])]),_:1}),e[18]||(e[18]=s(" 荣誉推出",-1))])])}const y=t(r,[["render",h]]);export{C as __pageData,y as default};
